revoke all on function private.project_business_record(text,text,text) from public,anon,authenticated;

create function private.sync_structured_record() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  perform private.project_business_record(new.company_id,new.section,new.record_id);
  return new;
end $$;
revoke all on function private.sync_structured_record() from public,anon,authenticated;
create trigger sync_structured_record after insert or update of payload,version,deleted,ordinal
  on public.business_records for each row execute function private.sync_structured_record();

create function public.backfill_structured_records(p_company text,p_section text,p_after bigint default 0,p_limit integer default 1000)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r record; v_after bigint:=p_after; v_count integer:=0; v_failed integer:=0; v_errors jsonb:='[]';
begin
  if p_after is null or p_after<0 or p_limit is null or p_limit not between 1 and 5000
    or not exists(select 1 from private.structured_sections where section=p_section)
    then raise exception 'INVALID_BACKFILL_REQUEST'; end if;
  for r in select record_id,ordinal from public.business_records
    where company_id=p_company and section=p_section and ordinal>p_after order by ordinal limit p_limit
  loop
    begin
      perform private.project_business_record(p_company,p_section,r.record_id);
      -- Force this batch's reference checks now so failures are reported,
      -- not deferred until after the worker has received its result.
      set constraints all immediate;
    exception when others then
      v_failed:=v_failed+1;
      if v_failed<=20 then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('recordId',r.record_id,'error',sqlerrm)); end if;
    end;
    v_after:=r.ordinal;v_count:=v_count+1;
  end loop;
  return jsonb_build_object('after',v_after,'processed',v_count,'failed',v_failed,'errors',v_errors,
    'done',not exists(select 1 from public.business_records where company_id=p_company and section=p_section and ordinal>v_after));
end $$;
revoke all on function public.backfill_structured_records(text,text,bigint,integer) from public,anon,authenticated;
grant execute on function public.backfill_structured_records(text,text,bigint,integer) to service_role;

-- Bounded structured reads for trusted API/reporting workers. User-facing
-- callers must still be authorized and projected by the existing Edge API.
create function public.structured_record_page(p_company text,p_section text,p_after bigint default 0,p_limit integer default 100)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_table text; v_result jsonb;
begin
  if p_after is null or p_after<0 or p_limit is null or p_limit not between 1 and 500 then raise exception 'INVALID_PAGE'; end if;
  select table_name into v_table from private.structured_sections where section=p_section;
  if v_table is null then raise exception 'INVALID_RECORD_SECTION'; end if;
  execute format('select coalesce(jsonb_agg(to_jsonb(p) order by ordinal),''[]''::jsonb) from
    (select * from business.%I where company_id=$1 and not deleted and ordinal>$2 order by ordinal limit $3) p',v_table)
    into v_result using p_company,p_after,p_limit;
  return v_result;
end $$;
revoke all on function public.structured_record_page(text,text,bigint,integer) from public,anon,authenticated;
grant execute on function public.structured_record_page(text,text,bigint,integer) to service_role;

create index audit_events_company_time on private.audit_events(company_id,created_at desc,id desc);
create index company_changes_expiry on public.company_changes(created_at);
alter table public.business_records add constraint records_known_section
  foreign key(section) references private.structured_sections(section) not valid;
alter table public.business_records add constraint records_payload_company
  check(not(payload ? 'companyId') or (payload->>'companyId') is not distinct from company_id) not valid;
alter table public.business_records add constraint records_payload_identity
  check(not(payload ? 'recordId') or (payload->>'recordId') is not distinct from record_id) not valid;
